/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst15600.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.comSelectInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.comSelectInit = function () {
    /* sdd-asis-lifecycle:begin comSelectInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('a.btn-choice').bind("click", async function() {
            let isCount = false;
            let isAlert = false;
            let html = "";
            $('table.org-data tr.active').each(async function() {
                    let chk = false;
                    const stkCd = $(this).find('input#stkCd').val();
                    $('table.choiced-data tr').each(function() {
                            const tmpCd = $(this).find('input#stkCd').val();
                            if (tmpCd === stkCd) {
                                chk = true;
                            }
                    });
                    if (chk === false) {
                        if (scwin.varSelCount + 1 <= 10) {
                            html += "<tr style='cursor: pointer;'>" + $(this).html() + "</tr>";
                            scwin.varSelCount++;
                            $(this).remove();
                        } else {
                            if (isCount === false) {
                                isCount = true;
                                await $c.win.alert('회사명을 10개 까지만 선택하실 수 있습니다.');
                            }
                        }
                    } else {
                        isAlert = true;
                    }
            });
            if (html !== "") {
                $('table.choiced-data tbody').append(html);
            }
            if (isAlert) {
                await $c.win.alert('선택된 회사명이 있습니다.');
            }
    });
    $('a.btn-cancel').bind("click", function() {
            let html = "";
            $('table.choiced-data tr.active').each(function() {
                    let chk = false;
                    const stkCd = $(this).find('input#stkCd').val();
                    $('table.org-data tr').each(function() {
                            const tmpCd = $(this).find('input#stkCd').val();
                            if (tmpCd === stkCd) {
                                chk = true;
                            }
                    });
                    if (chk === false) {
                        html += "<tr style='cursor: pointer;'>" + $(this).html() + "</tr>";
                    }
                    $(this).remove();
                    scwin.varSelCount--;
            });
            if (html !== "") {
                $('table.org-data tbody').append(html);
            }
    });
    function construct() {
        org_tbl_bind();
        choiced_tbl_bind();
    }
    function org_tbl_bind() {
        $('table.org-data td').live("click", function() {
                if ($(this).parent().hasClass("active")) {
                    $(this).parent().removeClass("active");
                } else {
                    $(this).parent().addClass("active");
                }
        });
    }
    function choiced_tbl_bind() {
        $('table.choiced-data td').live("click", function() {
                if ($(this).parent().hasClass("active")) {
                    $(this).parent().removeClass("active");
                } else {
                    $(this).parent().addClass("active");
                }
        });
    }
    construct();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.reflectCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.reflectCorpName = function () {
    /* sdd-asis-lifecycle:begin reflectCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let corpNameTmp = $c.util.getComponent('ipt_corpNameTmp').getValue(); if (corpNameTmp == null) { corpNameTmp = ''; }
    corpNameTmp = encodeURI(corpNameTmp);
    $c.util.getComponent('ipt_corpName').setValue(corpNameTmp);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#searchForm > #pageIndex").val("1");
    $c.util.getComponent('ipt_beginIndex').setValue("");
    clearBtnImage();
    scwin.reflectCorpName();
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


