/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let beginIdx = $c.util.getComponent('ipt_beginIndex').getValue(); if (beginIdx == null) { beginIdx = ''; }
    if (beginIdx === "") {
        let corpNameTmp = $c.util.getComponent('ipt_corpNameTmp').getValue(); if (corpNameTmp == null) { corpNameTmp = ''; }
        if (corpNameTmp === "") {
            await $c.win.alert("회사명 또는 종목코드을 입력해 주세요.");
            return;
        }
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchFinancialInfoOfCorpSelectSub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


