/**
 * @method
 * @name scwin.org_tbl_bind
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.org_tbl_bind = function () {
    /* sdd-asis-lifecycle:begin org_tbl_bind — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('table.org-data td').live("click", function() {
            if ($(this).parent().hasClass("active")) {
                $(this).parent().removeClass("active");
            } else {
                $(this).parent().addClass("active");
            }
    });
    /* sdd-asis-lifecycle:end */
};


